         * https:// URL the Swift side can hand to Kingfisher.
         */icon: String?) {
        self.url = url
        self.name = name
        self.description = description
        self.pubkey = pubkey
        self.contact = contact
        self.software = software
        self.version = version
        self.supportedNips = supportedNips
        self.icon = icon
    }
}

