public enum CoreError: Swift.Error {



    case NotInitialized(message: String)

    case NotAuthenticated(message: String)

    case InvalidInput(message: String)

    case Network(message: String)

    case Signer(message: String)

    case Relay(message: String)

    case Cache(message: String)

    case NotFound(message: String)

    case Other(message: String)

}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .NotInitialized(
            message: try FfiConverterString.read(from: &buf)
        )

        case 2: return .NotAuthenticated(
            message: try FfiConverterString.read(from: &buf)
        )

        case 3: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
        )

        case 4: return .Network(
            message: try FfiConverterString.read(from: &buf)
        )

        case 5: return .Signer(
            message: try FfiConverterString.read(from: &buf)
        )

        case 6: return .Relay(
            message: try FfiConverterString.read(from: &buf)
        )

        case 7: return .Cache(
            message: try FfiConverterString.read(from: &buf)
        )

        case 8: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
        )

        case 9: return .Other(
            message: try FfiConverterString.read(from: &buf)
        )


        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {




        case .NotInitialized(_ /* message is ignored*/):
            writeInt(&buf, Int32(1))
        case .NotAuthenticated(_ /* message is ignored*/):
            writeInt(&buf, Int32(2))
        case .InvalidInput(_ /* message is ignored*/):
            writeInt(&buf, Int32(3))
        case .Network(_ /* message is ignored*/):
            writeInt(&buf, Int32(4))
        case .Signer(_ /* message is ignored*/):
            writeInt(&buf, Int32(5))
        case .Relay(_ /* message is ignored*/):
            writeInt(&buf, Int32(6))
        case .Cache(_ /* message is ignored*/):
            writeInt(&buf, Int32(7))
        case .NotFound(_ /* message is ignored*/):
            writeInt(&buf, Int32(8))
        case .Other(_ /* message is ignored*/):
            writeInt(&buf, Int32(9))


        }
    }
}


